239	  const geo = new THREE.BoxGeometry(45, 20, 24);
240	  geo.translate(0, 12, 0);
241	  for (const t of things.values()) {
242	    if (t.attributes?.kind !== 'haul-truck') continue;
243	    const mat = new THREE.MeshLambertMaterial({ color: COLORS.empty });
244	    const mesh = pick(new THREE.Mesh(geo, mat), t.thingId);
245	    const l = label(t.thingId.split(':')[1].toUpperCase(), 'truck');
246	    l.position.set(0, 45, 0);
247	    mesh.add(l);
248	    scene.add(mesh);
249	    truckObjs.set(t.thingId, { mesh, mat, target: null, l });
250	  }
251	}
