254	function updateScene() {
255	  for (const [tid, o] of truckObjs) {
256	    const t = things.get(tid);
257	    const p = t.features?.position?.properties;
258	    if (!p) continue;
259	    o.target = V([p.x, p.y, p.z]);
260	    o.heading = -THREE.MathUtils.degToRad(p.heading || 0);
261	    if (!o.placed) { o.mesh.position.copy(o.target); o.placed = true; }
262	    const down = f(t, 'status') === 'down';
263	    const mat = f(t, 'payload', 'material');
264	    o.mat.color.copy(down ? COLORS.down : (f(t, 'payload') > 0 ? COLORS[mat] || COLORS.empty : COLORS.empty));
265	    o.l.element.textContent = `${tid.split(':')[1].toUpperCase()}${down ? ' ✕' : ''}`;
266	  }
267	  for (const [tid, o] of roadMeshes) {
268	    const t = things.get(tid);
269	    const closed = f(t, 'status') === 'closed' || desired(t, 'status') === 'closed';
270	    o.mat.color.set(closed ? COLORS.down : '#d8cfae');
271	    o.lbl.visible = closed;
272	    o.lbl.element.textContent = `ЗАКРЫТО: ${t.attributes.name}`;
273	  }
274	  for (const [tid, o] of shovelObjs) {
275	    const t = things.get(tid);
276	    const down = f(t, 'status') === 'down';
277	    o.body.material.color.set(down ? COLORS.down : '#f0a020');
278	    const q = f(t, 'queue') || 0;
279	    o.l.element.textContent = `${tid.split(':')[1].toUpperCase()} · ${down ? 'ОСТАНОВЛЕН' : `${f(t, 'production', 'plan_pct') ?? 0}% плана`}${q ? ` · очередь ${q}` : ''}`;
280	    o.l.element.className = `lbl site${down ? ' alert' : ''}`;
281	  }
282	  const cr = things.get(id('crusher'));
283	  const crDown = f(cr, 'status') === 'down';
284	  siteLabels.get(id('crusher')).element.textContent =
285	    `ЗКД · ${crDown ? 'ОСТАНОВЛЕНА' : `${fmt(f(cr, 'throughput'))} т/ч`} · бункер ${f(cr, 'bin', 'pct') ?? 0}%${f(cr, 'queue') ? ` · очередь ${f(cr, 'queue')}` : ''}`;
286	  siteLabels.get(id('crusher')).element.className = `lbl site${crDown ? ' alert' : ''}`;
287	  siteLabels.get(id('stockpile')).element.textContent = `Рудный склад · ${fmt(f(things.get(id('stockpile')), 'received'))} т`;
288	  siteLabels.get(id('leach')).element.textContent = `Кучное выщелачивание · ${fmt(f(things.get(id('leach')), 'received'))} т`;
289	  siteLabels.get(id('dump')).element.textContent = `Отвал · ${fmt(f(things.get(id('dump')), 'received'))} т`;
290	}
